<script setup>
import { computed, nextTick, onBeforeUnmount, ref } from 'vue';
import { request } from '../../api/http';
import { session } from '../../lib/session';
import { createRequestId } from '../../api/convox';
const emit=defineEmits(['saved']);
const dialog=ref(null), busy=ref(false), saving=ref(false), message=ref(''), error=ref('');
const branches=ref([]), leads=ref([]), schedules=ref([]), editing=ref(null), selected=ref(null);
const lead=ref(''), search=ref(''), branch=ref(''), date=ref(''), today=ref(''), duration=ref(45), role=ref(''), employee=ref('');
let generation=0, searchGeneration=0, searchTimer, requestId=createRequestId();
const designations=computed(()=>[...new Set(schedules.value.map(row=>row.staff.designation))].sort());
const employees=computed(()=>schedules.value.map(row=>row.staff).filter(staff=>!role.value||staff.designation===role.value));
const slots=computed(()=>schedules.value.find(row=>row.staff.id===employee.value)?.slots||[]);
const owner=computed(()=>leads.value.find(row=>row.name===lead.value)?.lead_owner_name||'Unassigned');
const formatTime=value=>{const [h,m]=String(value).slice(11,16).split(':');return `${Number(h)%12||12}:${m} ${Number(h)<12?'AM':'PM'}`};
async function call(action,args={}){return (await request('life_slimming.api.cc_appointments.'+action,{args,csrfToken:session.csrf_token})).message;}
function reset(){selected.value=null;requestId=createRequestId();}
function selectEmployee(){reset();if(!employees.value.some(staff=>staff.id===employee.value))employee.value=employees.value[0]?.id||'';}
async function refresh(){const token=++generation;reset();schedules.value=[];busy.value=true;error.value='';message.value='Checking available consultation slots…';try{const result=await call('calendar',{branch:branch.value,date:date.value,duration:Number(duration.value),appointment:editing.value?.name});if(token!==generation)return;schedules.value=result.schedules||[];if(!designations.value.includes(role.value))role.value='';selectEmployee();message.value=schedules.value.length?'Times shown in the clinic timezone. Unavailable slots are disabled.':'No eligible consultation employees are mapped to this branch.';}catch(e){if(token===generation)error.value=e.message;}finally{if(token===generation)busy.value=false;}}
async function open(id,preferred='',appointment=''){if(dialog.value?.open)return;generation++;reset();lead.value=id;search.value='';error.value='';message.value='Loading consultation booking…';busy.value=true;editing.value=null;leads.value=[];schedules.value=[];await nextTick();if(!dialog.value.open)dialog.value.showModal();const token=generation;try{const data=await call('bootstrap',{selected_lead:id||'',appointment:appointment||undefined});if(token!==generation)return;editing.value=data.appointment||null;leads.value=data.leads||[];branches.value=data.branches||[];today.value=data.today;date.value=data.today;branch.value=data.branches.includes(preferred)?preferred:(data.branches[0]||'');duration.value=45;role.value='';employee.value='';if(editing.value){branch.value=editing.value.branch;date.value=editing.value.start.slice(0,10)<data.today?data.today:editing.value.start.slice(0,10);duration.value=editing.value.duration;employee.value=editing.value.resource||'';}busy.value=false;if(branch.value)await refresh();else error.value='No branches are available for your account.';}catch(e){if(token===generation){error.value=e.message;busy.value=false;}}}
function searchLeads(){clearTimeout(searchTimer);const token=++searchGeneration;searchTimer=setTimeout(async()=>{try{const data=await call('bootstrap',{query:search.value,selected_lead:lead.value});if(token===searchGeneration&&dialog.value.open)leads.value=data.leads||[];}catch(e){if(token===searchGeneration)error.value=e.message;}},250);}
function selectSlot(slot){selected.value={staff:employees.value.find(staff=>staff.id===employee.value),slot};requestId=createRequestId();}
function close(){if(saving.value)return;generation++;searchGeneration++;clearTimeout(searchTimer);dialog.value?.close();}
async function confirm(){if(!selected.value||!lead.value||saving.value)return;saving.value=true;error.value='';message.value='Saving appointment…';try{const result=await call(editing.value?'reschedule':'book',{...(editing.value?{appointment:editing.value.name,modified:editing.value.modified}:{lead:lead.value,request_id:requestId}),branch:branch.value,resource:selected.value.staff.id,start:selected.value.slot.start,duration:Number(duration.value)});dialog.value.close();emit('saved',{...result,lead:lead.value});}catch(e){error.value=e.message||'Booking could not be confirmed. Retry or refresh availability.';}finally{saving.value=false;}}
onBeforeUnmount(()=>{generation++;searchGeneration++;clearTimeout(searchTimer);});
defineExpose({open});
</script>
<template>
<dialog ref="dialog" class="modal-box cc-summary-modal" @cancel="saving?$event.preventDefault():close()"><h2 class="modal-title">{{editing?'Reschedule / change manager':'Book a consultation'}}</h2><form id="cc-slot-form" class="cc-slot-form" @submit.prevent="confirm"><p class="cc-slot-intro">{{editing?'Current booking: '+editing.branch+' · '+editing.staff+' · '+editing.start+'. Choose a new date, manager or available slot.':'Choose a branch, employee designation and an available consultation time.'}}</p><p id="cc-slot-message" role="status" :class="{'cc-slot-error':error}">{{error||message}}</p><fieldset :disabled="busy||saving"><div class="cc-slot-fields"><label>Find lead<input id="cc-slot-search" v-model="search" :disabled="!!editing" placeholder="Name, mobile or Lead ID" @input="searchLeads"></label><label>Lead<select id="cc-slot-lead" v-model="lead" required :disabled="!!editing" @change="open(lead,branch)"><option value="">Select lead</option><option v-for="row in leads" :key="row.name" :value="row.name">{{row.lead_name}} · {{row.mobile_no||''}} · {{row.name}}</option></select></label><label>Lead owner<input id="cc-slot-owner" :value="owner" readonly></label><label>Branch<select id="cc-slot-branch" v-model="branch" required @change="refresh"><option v-for="item in branches" :key="item">{{item}}</option></select></label><label>Date<input id="cc-slot-date" v-model="date" type="date" :min="today" required @change="refresh"></label><label>Duration<select id="cc-slot-duration" v-model="duration" @change="refresh"><option :value="45">45 minutes</option><option :value="60">60 minutes</option></select></label><label>Designation<select id="cc-slot-role" v-model="role" @change="selectEmployee"><option value="">All eligible designations</option><option v-for="item in designations" :key="item">{{item}}</option></select></label><label>Consultation employee<select id="cc-slot-employee" v-model="employee" required @change="reset"><option value="">Select consultation employee</option><option v-for="staff in employees" :key="staff.id" :value="staff.id">{{staff.name}} · {{staff.designation}}</option></select></label></div><div id="cc-slot-times" class="cc-slot-times"><button v-for="slot in slots" :key="slot.start" type="button" :disabled="!slot.available" :title="slot.reason" :class="{chosen:selected?.slot.start===slot.start}" @click="selectSlot(slot)">{{formatTime(slot.start)}}–{{formatTime(slot.end)}}</button></div><p id="cc-slot-summary" class="cc-slot-summary">{{selected?selected.staff.name+' · '+selected.staff.designation+' · '+date+' · '+formatTime(selected.slot.start)+'–'+formatTime(selected.slot.end):'Select an available time.'}}</p><div class="cc-slot-actions"><button id="cc-slot-confirm" type="submit" class="btn btn-g" :disabled="!selected||!lead">{{editing?'Save appointment changes':'Confirm appointment'}}</button><button id="cc-slot-refresh" type="button" class="btn btn-gy" @click="refresh">Refresh availability</button></div></fieldset></form><div class="cc-modal-foot"><button class="btn btn-gy btn-sm" :disabled="saving" @click="close">Close</button></div></dialog>
</template>

<style scoped>
dialog{margin:auto;width:min(760px,calc(100vw - 32px));max-height:85dvh;overflow:auto;border:1px solid #cadbd0;border-radius:14px;padding:24px;color:#214638;background:white}dialog::backdrop{background:#112c2466}h2{margin-top:0}.cc-slot-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}label{display:grid;gap:6px;font-size:13px}input,select,button{font:inherit;padding:10px;border:1px solid #c8d8ce;border-radius:7px;color:inherit;background:white;min-width:0}fieldset{border:0;padding:0}button{cursor:pointer}button:disabled{cursor:not-allowed;opacity:.5}.cc-slot-times{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px}.cc-slot-times .chosen,.cc-slot-actions button[type=submit]{background:#166534;color:white}.cc-slot-actions{display:flex;gap:10px}.cc-modal-foot{margin-top:18px}.cc-slot-error{color:#a33324}.cc-slot-summary,.cc-slot-intro{line-height:1.5}@media(max-width:600px){.cc-slot-fields{grid-template-columns:1fr}dialog{padding:16px}}
</style>
